3112: # The row of an engine, or $null.
3113: function Get-EngineSpec {
3114:     param([string]$Name)
3115:     if ($Name -and $script:Engines.ContainsKey($Name)) { return $script:Engines[$Name] }
3116:     return $null
3117: }
3118: 
3119: # The launcher of an engine: $Explicit (codex: -CodexExe; others: -EngineExe), then the
3120: # engine's ExeEnv variable, then its LauncherNames on PATH, then (wave 23, D3) its vendor
3121: # install locations (InstallLaunchers: muse - %LOCALAPPDATA%\Programs\muse\muse.cmd on
3122: # Windows). An explicit launcher that does not resolve is an error (never a silent
3123: # fall-through to PATH); $null when none is found.
3124: function Resolve-EngineLauncher {
3125:     param([string]$Engine, [string]$Explicit = '')
3126:     if (-not $Engine -or $Engine -eq 'codex') { return (Resolve-CodexLauncher -Explicit $Explicit) }
3127:     $spec = Get-EngineSpec -Name $Engine
3128:     if (-not $spec) { return $null }
3129:     $sources = @(@{ value = $Explicit; label = '-EngineExe' }, @{ value = [Environment]::GetEnvironmentVariable($spec.ExeEnv); label = $spec.ExeEnv })
3130:     foreach ($source in $sources) {
3131:         $candidate = [string]$source.value
3132:         if ($candidate) {
3133:             if (Test-Path -LiteralPath $candidate) { return (Resolve-Path -LiteralPath $candidate).Path }
3134:             $cmd = Get-Command $candidate -CommandType Application -ErrorAction SilentlyContinue
3135:             if ($cmd) { return @($cmd)[0].Source }
3136:             Stop-WithError "$($source.label) '$candidate' is not a file and not an application on PATH."
3137:         }
3138:     }
3139:     foreach ($name in @($spec.LauncherNames)) {
3140:         $cmd = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue
3141:         if ($cmd) { return @($cmd)[0].Source }
3142:     }
3143:     foreach ($il in @($spec.InstallLaunchers)) {
3144:         if ($null -eq $il) { continue }
3145:         $base = [string][Environment]::GetEnvironmentVariable([string]$il.Env)
3146:         if (-not $base.Trim()) { continue }
3147:         $candidate = Join-Path $base ([string]$il.Rel)
3148:         if (Test-Path -LiteralPath $candidate -PathType Leaf) { return (Resolve-Path -LiteralPath $candidate).Path }
3149:     }
3150:     return $null
3151: }
3152: 
3153: # The engine -EngineExe names (wave 23, D3): the SELECTED engine other than codex - -Engine's
3154: # when given (codex is refused: it takes -CodexExe); else the one the run can select: the
3155: # roster entry of -Provider (codex-providers: of the -Provider row), else the only engine other
3156: # than codex among the roster's entries. None or several -> refused ("pass -Engine <name>").
3157: # { Engine; Error }.
3158: function Resolve-EngineExeBinding {
3159:     param([string]$Engine = '', $Roster = $null, [string]$Provider = '', [string]$Model = '')
3160:     $r = [pscustomobject]@{ Engine = ''; Error = '' }
3161:     $others = @($script:EngineNames | Where-Object { $_ -ne 'codex' })
3162:     if ($Engine) {
3163:         if ($Engine -eq 'codex') { $r.Error = "-EngineExe names the launcher of an engine other than codex ($($others -join ', ')); codex takes -CodexExe"; return $r }
3164:         $r.Engine = $Engine
3165:         return $r
3166:     }
3167:     if ($Provider) {
3168:         $pe = Find-RosterEntry -Roster $Roster -Provider $Provider -Model $Model
3169:         if ($pe -and $pe.Engine -ne 'codex') { $r.Engine = [string]$pe.Engine; return $r }
3170:         if ($pe) { $r.Error = "-EngineExe: the roster entry $($pe.Position) for -Provider $Provider is engine codex, which takes -CodexExe"; return $r }
3171:     }
3172:     $used = New-Object System.Collections.Generic.List[string]
3173:     if ($Roster -and $Roster.Exists) {
3174:         foreach ($e in @($Roster.Entries)) { $en = [string]$e.Engine; if ($en -and $en -ne 'codex' -and -not $used.Contains($en)) { $used.Add($en) } }
3175:     }
3176:     if ($used.Count -eq 1) { $r.Engine = $used[0]; return $r }
3177:     if ($used.Count -gt 1) { $r.Error = "-EngineExe is ambiguous: the reviewer roster has entries of the engines $($used.ToArray() -join ' and '); pass -Engine <$($others -join '|')> to name the one it launches" }
3178:     else { $r.Error = "-EngineExe names the launcher of an engine other than codex: pass -Engine <$($others -join '|')> with it" }
3179:     return $r
3180: }
