3182: # The launcher of $Engine for a walk over the roster: codex -> $CodexLauncher; any other engine
3183: # is resolved once per $Launchers table (engine -> path, '' = not found).
3184: function Get-EngineLauncher {
3185:     param([string]$Engine, [hashtable]$Launchers = $null, [string]$CodexLauncher = '')
3186:     if (-not $Engine -or $Engine -eq 'codex') { return $CodexLauncher }
3187:     if ($null -ne $Launchers -and $Launchers.ContainsKey($Engine)) { return [string]$Launchers[$Engine] }
3188:     $p = [string](Resolve-EngineLauncher -Engine $Engine)
3189:     if ($null -ne $Launchers) { $Launchers[$Engine] = $p }
3190:     return $p
3191: }
